function mulberrySymbol(item: MulberrySymbolInventoryItem): VocabularySymbolMetadata {
  return {
    symbolAssetId: item.label,
    symbolAssetLocation: `symbols/${item.fileName}`,
    symbolDescription: item.description,
    symbolSource: MULBERRY_SYMBOL_SOURCE,
    symbolCreator: MULBERRY_SYMBOL_CREATOR,
    symbolLicenseId: MULBERRY_SYMBOL_LICENSE_ID,
    symbolLicenseUrl: MULBERRY_SYMBOL_LICENSE_URL,
    symbolModified: item.modified ?? false,
    ...(item.sourceAssets ? { symbolSourceAssets: item.sourceAssets.map((asset) => `symbols/${asset}.svg`) } : {}),
  };
}

const mulberrySymbolMetadataByVocabularyId: Record<string, VocabularySymbolMetadata> = Object.fromEntries(
  MULBERRY_SYMBOL_INVENTORY.flatMap((item) => item.vocabularyIds.map((id) => [id, mulberrySymbol(item)])),
);

function symbol(symbolAssetId: string, symbolDescription: string): VocabularySymbolMetadata {
  return {
    symbolAssetId,
    symbolAssetLocation: STARTER_SYMBOL_ASSET_LOCATION,
    symbolDescription,
    symbolSource: STARTER_SYMBOL_SOURCE,
    symbolCreator: STARTER_SYMBOL_CREATOR,
    symbolLicenseId: STARTER_SYMBOL_LICENSE_ID,
  };
}

